import ComponentFactory from './ComponentFactory.js';
import Icons from './utils/Icons.js';

class Main {
  constructor() {
    this.init();
  }

  init() {
    document.documentElement.classList.add('has-js');

    Icons.load();

    // Allez ajouter vos composantes
    // new ComponentFactory();
    new ComponentFactory();

    const robot = document.querySelector('[data-parallax]');

    if (robot) {
      const reduceMotion = window.matchMedia(
        '(prefers-reduced-motion: reduce)',
      );
      const finePointer = window.matchMedia(
        '(hover: hover) and (pointer: fine)',
      );

      let targetX = 0;
      let targetY = 0;
      let currentX = 0;
      let currentY = 0;
      let animationFrame;

      function animate() {
        currentX += (targetX - currentX) * 0.08;
        currentY += (targetY - currentY) * 0.08;

        robot.style.setProperty('--parallax-x', `${currentX}px`);
        robot.style.setProperty('--parallax-y', `${currentY}px`);

        if (
          Math.abs(targetX - currentX) > 0.1 ||
          Math.abs(targetY - currentY) > 0.1
        ) {
          animationFrame = requestAnimationFrame(animate);
        } else {
          animationFrame = null;
        }
      }

      function updatePosition(x, y) {
        targetX = x;
        targetY = y;

        if (!animationFrame) {
          animationFrame = requestAnimationFrame(animate);
        }
      }

      function resetPosition() {
        updatePosition(0, 0);
      }

      if (!reduceMotion.matches && finePointer.matches) {
        document.addEventListener('mousemove', (event) => {
          const x = event.clientX / window.innerWidth - 0.5;
          const y = event.clientY / window.innerHeight - 0.5;

          // Mouvement subtil : maximum d'environ 16 px
          updatePosition(x * 32, y * 32);
        });

        document.addEventListener('mouseleave', resetPosition);
      }
    }
  }
}
new Main();
