import Swiper from 'swiper/bundle';

export default class Carousel {
  constructor(element) {
    this.element = element;

    this.options = {
      slidesPerView: 1.4,
      spaceBetween: 60,
      speed: 1100,

      scrollbar: {
        el: this.element.querySelector('.swiper-scrollbar'),
        draggable: true,
        hide: false,
        snapOnRelease: true,
      },

      navigation: {
        nextEl: this.element.querySelector('.swiper-button-next'),
        prevEl: this.element.querySelector('.swiper-button-prev'),
      },

      on: {
        init: (swiper) => this.updateCardAngles(swiper),
        setTranslate: (swiper) => this.updateCardAngles(swiper),
        resize: (swiper) => this.updateCardAngles(swiper),
        transitionEnd: (swiper) => this.updateCardAngles(swiper),
      },
    };

    this.setOptions();
    this.init();
  }

  updateCardAngles(swiper) {
    const containerCenter = swiper.width / 2;

    swiper.slides.forEach((slide) => {
      const slideCenter =
        slide.offsetLeft + slide.offsetWidth / 2 + swiper.translate;

      const distance = slideCenter - containerCenter;

      // Normalise la distance pour obtenir un angle progressif.
      const normalizedDistance = Math.max(
        -1,
        Math.min(1, distance / (swiper.width * 0.65)),
      );

      // À gauche : angle positif.
      // À droite : angle négatif.
      const angle = -normalizedDistance * 12;

      slide.style.setProperty('--card-angle', `${angle}deg`);
    });
  }

  init() {
    this.swiper = new Swiper(this.element, this.options);
  }

  setOptions() {
    if ('split' in this.element.dataset) {
      this.options.breakpoints = {
        600: {
          slidesPerView: 2.2,
          spaceBetween: 30,
        },
        900: {
          slidesPerView: 3.8,
          spaceBetween: 60,
        },
      };
    }

    if ('autoplay' in this.element.dataset) {
      this.options.autoplay = {
        delay: Number(this.element.dataset.autoplayDelay) || 5000,
        pauseOnMouseEnter: true,
        disableOnInteraction: false,
      };
    }

    if ('loop' in this.element.dataset) {
      this.options.loop = true;
    }

    if ('slides' in this.element.dataset) {
      this.options.slidesPerView = 2.5;
    }
  }
}
