export default class Header {
  constructor(element) {
    this.element = element;
    this.options = {
      treshold: 0.3,
    };
    this.scrollPosition = 0;
    this.lastScrollPosition = 0;
    this.html = document.documentElement;
    this.init();
    this.initNavMobile();
  }
  init() {
    this.setOptions();

    window.addEventListener('scroll', this.onScroll.bind(this));
  }
  setOptions() {
    // vérifier les différents attributs data sur la composante
  }

  onScroll() {
    this.lastScrollPosition = this.scrollPosition;
    this.scrollPosition = document.scrollingElement.scrollTop;

    this.setHeaderState();
    this.setDirections();
  }

  setHeaderState() {
    if (
      this.scrollPosition >
      document.scrollingElement.scrollHeight * this.options.treshold
    ) {
      this.html.classList.add('header-is-hidden');
    } else if (this.scrollPosition < this.lastScrollPosition) {
      this.html.classList.remove('header-is-hidden');
    }
  }

  setDirections() {
    if (this.scrollPosition >= this.lastScrollPosition) {
      this.html.classList.add('is-scrolling-down');
      this.html.classList.remove('is-scrolling-up');
    } else {
      this.html.classList.add('is-scrolling-up');
      this.html.classList.remove('is-scrolling-down');
    }
  }
  initNavMobile() {
    const toggle = this.element.querySelector('.js-toggle');
    const navLinks = this.element.querySelectorAll('.nav-primary a');

    toggle.addEventListener('click', this.onToggleNav.bind(this));
    navLinks.forEach((link) => {
      link.addEventListener('click', this.onCloseNav.bind(this));
    });
  }
  onToggleNav() {
    const isActive = this.html.classList.toggle('nav-is-active');
    const toggle = this.element.querySelector('.js-toggle');

    toggle.setAttribute('aria-expanded', isActive.toString());
    toggle.setAttribute('aria-label', isActive ? 'Fermer le menu' : 'Ouvrir le menu');
  }
  onCloseNav() {
    this.html.classList.remove('nav-is-active');

    const toggle = this.element.querySelector('.js-toggle');
    toggle.setAttribute('aria-expanded', 'false');
    toggle.setAttribute('aria-label', 'Ouvrir le menu');
  }
}
